'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const escapeHTML = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cleanup = () => {};
const labs = [
 ['controls','Basic controls','FOUNDATIONS','Get comfortable with inputs, selects, and the small details that make reliable tests.', ['Enter your name and email, then choose Poland.','Select two tools, choose Pro, and accept the terms.','Save the profile and assert every value in the summary.'], 'Labels, roles, filling fields, native selects, radio buttons, checkboxes, form validation.', controls],
 ['locators','Locator workshop','FOUNDATIONS','Find the right element when several controls look exactly alike.', ['Add the headphones from the Featured collection only.','Assert that its quantity is 1 and the Archive quantity remains 0.','Open the delivery details and verify the message.'], 'Scoped locators, repeated text, filtering by content, accessible names, test IDs.', locators],
 ['timing','Waiting & async UI','INTERMEDIATE','Practice synchronization against predictable changes, without arbitrary sleeps.', ['Load the report and observe the loading state.','Wait for “Report ready” and verify the total of 42.','Wait for the approval button to enable, then approve the report.'], 'Auto-waiting, visibility, enabled states, retrying assertions, fixed delayed rendering.', timing],
 ['tables','Data tables','INTERMEDIATE','Search, filter, sort, and act on rows across multiple pages.', ['Filter to Active and search for “a”.','Sort by name and navigate through the results.','Reset, find Olivia Martin, and deactivate only her account.'], 'Tables, row scoping, pagination, sorting, empty states, confirmation dialogs.', tables],
 ['dialogs','Dialogs & windows','INTERMEDIATE','Work with browser dialogs, accessible modals, and a second tab.', ['Trigger the alert, then accept and dismiss separate confirmation attempts.','Enter “Ada” in the prompt and verify the greeting.','Save a project in the modal, then open the help page in a new tab.'], 'Dialog events, prompts, modal focus, popups, cross-page assertions.', dialogs],
 ['files','Files & downloads','INTERMEDIATE','Choose local files and download a deterministic CSV report.', ['Upload fixtures/notes.txt and inspect its name, size, and content.','Choose multiple files and assert the displayed file count.','Download the report and verify its filename and CSV contents.'], 'File inputs, file chooser events, multiple uploads, download events and saved contents.', files],
 ['boundaries','Frames & shadow DOM','ADVANCED','Interact across document boundaries and inside a custom element.', ['Enter LAB-2026 in the embedded verification frame.','Verify that both the frame and parent show success.','Turn on notifications inside the shadow component.'], 'Frame locators, same-origin iframes, open shadow roots, custom elements.', boundaries],
 ['board','Drag & keyboard','ADVANCED','Move tasks across a board and edit a note with keyboard interaction.', ['Drag “Write first test” from To do into In progress.','Move it to Done using the accessible select alternative.','Edit the note and use Control+Enter or Command+Enter to save.'], 'HTML drag-and-drop, keyboard shortcuts, contenteditable, accessible alternatives.', board],
 ['network','Network lab','ADVANCED','Exercise real HTTP requests with controlled success, failure, and empty responses.', ['Load products and verify that four items are returned.','Force a 503 error, then switch it off and retry.','Search for “hub”, then try replacing the API response in your own test.'], 'Request/response events, route interception, HTTP errors, loading and empty states.', network],
 ['checkout','Checkout challenge','CHALLENGE','Bring it all together: a complete purchase with inventory, validation, and a real order request.', ['Add one keyboard and one USB-C hub; verify the subtotal is $134.00.','Continue with your email, apply LEARN10, and choose Express delivery.','Place the order and assert ORD-1001 with a total of $132.60.','Reset and cover an empty cart, invalid coupon, and a failed order request.'], 'Multi-step workflows, API mocking, validation, computed totals, network failures, order confirmation.', checkout],
 ['storage','Session & storage','ADVANCED','Practice browser context isolation with a deliberately simple local demo session.', ['Sign in using learner@example.com and practice123.','Reload and verify the session survives in this tab.','Sign out and verify the login form returns.','Save a theme preference, reload, and verify it persists.'], 'Session storage, local storage, context isolation, reloads. This is simulated login, not secure authentication. Playwright storageState does not include sessionStorage.', storage],
];
const panel = $('#playground');
function result(text, error = false, selector = '#result') { const el = $(selector); el.textContent = text; el.classList.toggle('error', error); }
function status() { return '<output id="result" class="result" aria-live="polite" data-testid="result"></output>'; }
function render() {
 cleanup(); cleanup = () => {};
 const id = location.hash.slice(1) || 'controls';
 const lab = labs.find(l => l[0] === id) || labs[0];
 $('#navigation').innerHTML = labs.map((l,i) => `<a href="#${l[0]}" ${l===lab?'class="active" aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${l[1]}</a>`).join('');
 $('#breadcrumb').textContent = lab[1]; $('#title').textContent = lab[1]; $('#level').textContent = lab[2]; $('#description').textContent = lab[3];
 $('#missions').innerHTML = lab[4].map(m=>`<li>${m}</li>`).join(''); $('#concepts').textContent = lab[5];
 const lesson = window.LAB_CURRICULUM[lab[0]];
 $('#feature-guide').innerHTML = `<details><summary>Python features to use</summary><ul class="api-list">${lesson.features.map(f=>`<li><code>${escapeHTML(f)}</code></li>`).join('')}</ul><p>${escapeHTML(lesson.hint)}</p><a href="guide.html">How to approach the tasks →</a></details>`;
 $('#assignments').innerHTML = lesson.tasks.map(([title,task,done])=>`<article class="assignment"><h3>${escapeHTML(title)}</h3><p>${escapeHTML(task)}</p><details><summary>Completion criteria</summary><p>${escapeHTML(done)}</p></details></article>`).join('') + `<p class="doc-links">Official Python docs: ${lesson.docs.map(slug=>`<a href="https://playwright.dev/python/docs/${slug}" target="_blank" rel="noopener">${slug}</a>`).join(' · ')}</p>`;
 $('#exercise-number').textContent = `EXERCISE ${String(labs.indexOf(lab)+1).padStart(2,'0')} / ${labs.length}`;
 panel.innerHTML = ''; lab[6]();
 document.title = `${lab[1]} · Playwright Lab`;
}
$('#reset').onclick = () => { if(location.hash === '#storage'){ sessionStorage.removeItem('lab-session'); localStorage.removeItem('lab-theme'); } render(); };
window.addEventListener('hashchange', render);
function controls(){
 panel.innerHTML = `<h2>Create your learner profile</h2><form id="profile"><div class="grid"><div class="field"><label for="name">Full name</label><input id="name" name="name" placeholder="e.g. Ada Lovelace" required></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" placeholder="ada@example.com" required></div></div><div class="grid"><div class="field"><label for="country">Country</label><select id="country" name="country" required><option value="">Choose a country</option><option>Poland</option><option>Germany</option><option>United Kingdom</option><option>United States</option></select></div><div class="field"><label for="tools">Tools <span class="muted">(select multiple)</span></label><select id="tools" name="tools" multiple size="3"><option>Playwright</option><option>Python</option><option>TypeScript</option></select></div></div><fieldset><legend>Learning plan</legend><label class="inline"><input type="radio" name="plan" value="Starter" checked>Starter</label><label class="inline"><input type="radio" name="plan" value="Pro">Pro</label></fieldset><div class="field"><label for="start">Start date</label><input id="start" name="start" type="date" value="2026-01-15"></div><label class="inline"><input type="checkbox" name="terms" required>I accept the practice terms</label><div class="divider"></div><button>Save profile</button></form>${status()}`;
 $('#profile').onsubmit = e => {e.preventDefault();const f=new FormData(e.target);result(`Profile saved\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nCountry: ${f.get('country')}\nTools: ${f.getAll('tools').join(', ') || 'None'}\nPlan: ${f.get('plan')}\nStart date: ${f.get('start')}\nTerms accepted: Yes`);};
}
function locators(){
 panel.innerHTML = `<h2>A little ambiguity</h2><p>Identical names. Different collections.</p><div class="grid">${['Featured','Archive'].map(group=>`<section class="product" aria-label="${group}" data-testid="${group.toLowerCase()}"><span class="tag">${group}</span><h3 style="margin-top:18px">Studio headphones</h3><p>Quantity: <strong class="quantity">0</strong></p><button>Add to cart</button></section>`).join('')}</div><div class="divider"></div><details><summary>Delivery details</summary><p style="margin-top:15px">Free delivery on orders over $100.</p></details>${status()}`;
 $$('.product button').forEach(b=>b.onclick=()=>{const card=b.closest('section');const q=$('.quantity',card);q.textContent=Number(q.textContent)+1;result(`${card.getAttribute('aria-label')}: headphones added`);});
}
function timing(){
 panel.innerHTML=`<h2>Monthly report</h2><p>The report appears after 1.2 seconds. Approval unlocks 0.8 seconds later.</p><button id="load">Load report</button><div id="report" aria-live="polite"></div>${status()}`;
 const timers=[]; cleanup=()=>timers.forEach(clearTimeout);
 $('#load').onclick=()=>{$('#load').disabled=true;$('#report').innerHTML='<div class="result" role="status">Preparing report…</div>';timers.push(setTimeout(()=>{$('#report').innerHTML='<div class="divider"></div><span class="tag">Report ready</span><h3 style="margin-top:20px">Total transactions: <span data-testid="transaction-count">42</span></h3><button id="approve" disabled>Approve report</button>';$('#approve').onclick=()=>{result('Report approved');$('#approve').disabled=true;};timers.push(setTimeout(()=>{$('#approve').disabled=false;},800));},1200));};
}
function tables(){
 let people=['Olivia Martin','Liam Chen','Emma Wilson','Noah Davis','Amelia Brown','Elijah Garcia','Sophia Miller','James Taylor','Charlotte Lee','Lucas Anderson','Mia Thomas','Henry White'].map((name,i)=>({id:i+1,name,status:i%3===2?'Inactive':'Active'}));let page=1,ascending=true;
 panel.innerHTML=`<h2>Team directory</h2><div class="grid"><div class="field"><label for="search">Search people</label><input id="search" type="search" placeholder="Search by name"></div><div class="field"><label for="filter">Status</label><select id="filter"><option>All</option><option>Active</option><option>Inactive</option></select></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th id="name-header" aria-sort="ascending"><button class="secondary" id="sort">Name ↑</button></th><th>Status</th><th>Action</th></tr></thead><tbody></tbody></table></div><div class="pagination"><button class="secondary" id="previous">Previous</button><span id="pages" class="muted"></span><button class="secondary" id="next">Next</button></div>${status()}`;
 function draw(){const rows=people.filter(p=>p.name.toLowerCase().includes($('#search').value.toLowerCase())&&($('#filter').value==='All'||p.status===$('#filter').value)).sort((a,b)=>(ascending?1:-1)*a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(rows.length/4));page=Math.min(page,pages);$('tbody').innerHTML=rows.slice((page-1)*4,page*4).map(p=>`<tr><td>${String(p.id).padStart(3,'0')}</td><td>${p.name}</td><td><span class="tag ${p.status==='Inactive'?'warning':''}">${p.status}</span></td><td><button class="secondary" data-id="${p.id}">${p.status==='Active'?'Deactivate':'Activate'}</button></td></tr>`).join('')||'<tr><td colspan="4">No people found</td></tr>';$('#pages').textContent=`Page ${page} of ${pages} · ${rows.length} people`;$('#previous').disabled=page===1;$('#next').disabled=page===pages;$$('tbody button').forEach(b=>b.onclick=()=>{const p=people.find(p=>p.id===Number(b.dataset.id));if(confirm(`${b.textContent} ${p.name}?`)){p.status=p.status==='Active'?'Inactive':'Active';result(`${p.name} is now ${p.status.toLowerCase()}`);draw();}});}
 $('#search').oninput=$('#filter').onchange=()=>{page=1;draw();};$('#sort').onclick=()=>{ascending=!ascending;$('#sort').textContent=`Name ${ascending?'↑':'↓'}`;$('#name-header').setAttribute('aria-sort',ascending?'ascending':'descending');draw();};$('#previous').onclick=()=>{page--;draw();};$('#next').onclick=()=>{page++;draw();};draw();
}
function dialogs(){
 panel.innerHTML=`<h2>Browser & page dialogs</h2><p>Each action exposes a different browser interaction.</p><div class="row"><button id="alert">Show alert</button><button id="confirm" class="secondary">Confirm action</button><button id="prompt" class="secondary">Enter name</button></div><div class="divider"></div><div class="row"><button id="open-modal">Create project</button><a href="help.html" target="_blank" rel="noopener">Open help in new tab ↗</a></div><dialog aria-labelledby="modal-title"><form id="project"><h2 id="modal-title">Create project</h2><div class="field"><label for="project-name">Project name</label><input id="project-name" required autofocus></div><div class="row"><button>Save project</button><button class="secondary" type="button" id="close-modal">Cancel</button></div></form></dialog>${status()}`;
 $('#alert').onclick=()=>{alert('Hello from Playwright Lab!');result('Alert acknowledged');};$('#confirm').onclick=()=>result(confirm('Continue with this action?')?'Action confirmed':'Action cancelled');$('#prompt').onclick=()=>{const name=prompt('What is your name?');result(name===null?'Prompt cancelled':`Hello, ${name}!`);};$('#open-modal').onclick=()=>$('dialog').showModal();$('#close-modal').onclick=()=>$('dialog').close();$('#project').onsubmit=e=>{e.preventDefault();result(`Project created: ${$('#project-name').value}`);$('dialog').close();};
}
function files(){
 panel.innerHTML=`<h2>File desk</h2><div class="field"><label for="upload">Text files</label><input id="upload" type="file" accept=".txt,.csv,.json,text/*" multiple></div><p class="muted">Preview reads the first 4 KB of each file. Files stay in your browser.</p><div id="file-list"></div><div class="divider"></div><button id="download">Download report</button>${status()}`;
 let readVersion=0;cleanup=()=>{readVersion++;};$('#upload').onchange=async e=>{const version=++readVersion;const selected=[...e.target.files];const previews=await Promise.all(selected.map(async f=>`<div class="result"><strong>${escapeHTML(f.name)}</strong> · ${f.size} bytes<pre>${escapeHTML(await f.slice(0,4096).text())}</pre></div>`));if(version!==readVersion)return;$('#file-list').innerHTML=previews.join('');result(`${selected.length} file(s) selected`);};$('#download').onclick=()=>{const a=document.createElement('a');a.href='report.csv';a.download='practice-report.csv';a.click();result('Report download started');};
}
function boundaries(){
 panel.innerHTML=`<h2>Embedded verification</h2><iframe src="frame.html" title="Verification widget"></iframe><div class="divider"></div><h2>Notification component</h2><lab-notifications></lab-notifications>${status()}`;
 const listener=e=>{if(e.origin===location.origin&&e.source===$('iframe')?.contentWindow&&e.data==='verified')result('Parent received: verification complete');};window.addEventListener('message',listener);cleanup=()=>window.removeEventListener('message',listener);
}
class Notifications extends HTMLElement{connectedCallback(){if(this.shadowRoot)return;const root=this.attachShadow({mode:'open'});root.innerHTML='<style>:host{display:block;padding:20px;background:#f3f6ee;border-radius:8px;font:14px system-ui}button{padding:10px 15px;border:1px solid #25533f;border-radius:5px;background:#25533f;color:white;cursor:pointer}p{color:#4a6344}</style><button role="switch" aria-checked="false">Email notifications</button><p role="status">Notifications off</p>';root.querySelector('button').onclick=e=>{const on=e.target.getAttribute('aria-checked')!=='true';e.target.setAttribute('aria-checked',String(on));root.querySelector('p').textContent=`Notifications ${on?'on':'off'}`;};}}
customElements.define('lab-notifications',Notifications);
function board(){
 const tasks=[{id:'task-1',name:'Write first test',lane:'To do'},{id:'task-2',name:'Review locators',lane:'To do'},{id:'task-3',name:'Explore assertions',lane:'In progress'}];const lanes=['To do','In progress','Done'];
 panel.innerHTML=`<h2>Practice board</h2><div class="board"></div><div class="divider"></div><label for="note">Session note</label><div id="note" role="textbox" aria-multiline="true" contenteditable="true" style="border:1px solid #d7dfd3;border-radius:6px;padding:15px">My next learning goal…</div><p class="muted" style="margin-top:10px">Save with Ctrl+Enter / ⌘+Enter.</p>${status()}`;
 function move(id,lane){const task=tasks.find(t=>t.id===id);if(!task)return;task.lane=lane;draw();result(`${task.name} moved to ${lane}`);}
 function draw(){$('.board').innerHTML=lanes.map(l=>`<section class="lane" aria-label="${l}"><h3>${l}</h3>${tasks.filter(t=>t.lane===l).map(t=>`<article class="task" draggable="true" id="${t.id}"><span>${t.name}</span><select aria-label="Move ${t.name}">${lanes.map(v=>`<option ${v===l?'selected':''}>${v}</option>`).join('')}</select></article>`).join('')}</section>`).join('');$$('.task').forEach(t=>{t.ondragstart=e=>e.dataTransfer.setData('text/plain',t.id);$('select',t).onchange=e=>move(t.id,e.target.value);});$$('.lane').forEach(l=>{l.ondragover=e=>e.preventDefault();l.ondrop=e=>{e.preventDefault();move(e.dataTransfer.getData('text/plain'),l.getAttribute('aria-label'));};});}draw();$('#note').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();result(`Note saved: ${e.currentTarget.textContent}`);}};
}
function network(){
 panel.innerHTML=`<h2>Warehouse API</h2><div class="field"><label for="query">Product search</label><input id="query" placeholder="e.g. hub"></div><label class="inline"><input id="fail" type="checkbox">Force HTTP 503</label><div class="row" style="margin-top:20px"><button id="fetch">Load products</button><code>GET /api/products</code></div>${status()}<div id="products" class="grid" style="margin-top:20px"></div>`;
 const controller=new AbortController();cleanup=()=>controller.abort();$('#fetch').onclick=async()=>{const button=$('#fetch');button.disabled=true;result('Loading products…');$('#products').innerHTML='';try{const response=await fetch(`/api/products?q=${encodeURIComponent($('#query').value)}&fail=${$('#fail').checked?1:0}`,{signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(`HTTP ${response.status}: ${data.error}`);if(!Array.isArray(data.products))throw Error('Invalid products response');$('#products').innerHTML=data.products.map(p=>`<article class="product"><h3>${escapeHTML(p.name)}</h3><span>$${Number(p.price).toFixed(2)}</span></article>`).join('');result(data.products.length?`${data.products.length} products loaded`:'No products found');}catch(e){if(e.name!=='AbortError')result(e.message,true);}finally{button.disabled=false;}};
}
function checkout(){
 const products=[{id:'P101',name:'Mechanical keyboard',price:89,stock:8},{id:'P102',name:'Studio headphones',price:129,stock:5},{id:'P103',name:'USB-C hub',price:45,stock:12},{id:'P104',name:'Desk lamp',price:35,stock:0}];const cart={};let step=1;let email='',coupon='',shipping='standard';const controller=new AbortController();cleanup=()=>controller.abort();
 const subtotal=()=>products.reduce((sum,p)=>sum+p.price*(cart[p.id]||0),0);const total=()=>subtotal()*(coupon==='LEARN10'?.9:1)+(shipping==='express'?12:0);
 function draw(){panel.innerHTML=`<div class="step">STEP ${step} OF 3 · ${['CHOOSE PRODUCTS','DELIVERY & DISCOUNT','REVIEW ORDER'][step-1]}</div><div class="progress"><div style="width:${step/3*100}%"></div></div><div id="checkout-body"></div>${status()}`;const body=$('#checkout-body');if(step===1){body.innerHTML=`<h2>Build your desk setup</h2><div class="grid">${products.map(p=>`<article class="product"><h3>${p.name}</h3><p>${p.stock?p.stock+' available':'Out of stock'}</p><div class="price">$${p.price.toFixed(2)}</div><label for="qty-${p.id}">Quantity</label><input id="qty-${p.id}" type="number" min="0" max="${p.stock}" value="${cart[p.id]||0}" ${p.stock?'':'disabled'} data-product="${p.id}"></article>`).join('')}</div><div class="divider"></div><h3>Subtotal: <span id="subtotal">$${subtotal().toFixed(2)}</span></h3><button id="continue" ${subtotal()===0?'disabled':''}>Continue to delivery</button>`;$$('[data-product]').forEach(i=>i.oninput=()=>{const valid=$$('[data-product]').every(el=>el.validity.valid&&el.value!=='');if(i.validity.valid)cart[i.dataset.product]=Number(i.value);$('#subtotal').textContent=`$${subtotal().toFixed(2)}`;$('#continue').disabled=!valid||subtotal()===0;});$('#continue').onclick=()=>{step=2;draw();};}else if(step===2){body.innerHTML=`<h2>Delivery details</h2><form id="delivery"><div class="field"><label for="order-email">Email address</label><input id="order-email" type="email" value="${escapeHTML(email)}" required></div><div class="field"><label for="coupon">Coupon code</label><input id="coupon" value="${escapeHTML(coupon)}" placeholder="Try LEARN10"><small class="muted">LEARN10 takes 10% off products.</small></div><div class="field"><label for="shipping">Delivery method</label><select id="shipping"><option value="standard">Standard · free</option><option value="express">Express · $12.00</option></select></div><div class="row"><button type="button" id="back" class="secondary">Back to cart</button><button>Review order</button></div></form>`;$('#shipping').value=shipping;$('#back').onclick=()=>{step=1;draw();};$('#delivery').onsubmit=e=>{e.preventDefault();email=$('#order-email').value;coupon=$('#coupon').value;shipping=$('#shipping').value;if(coupon&&coupon!=='LEARN10'){result('Unknown coupon. Use LEARN10 or leave it empty.',true);return;}step=3;draw();};}else{body.innerHTML=`<h2>Review your order</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Amount</th></tr></thead><tbody>${products.filter(p=>cart[p.id]>0).map(p=>`<tr><td>${p.name}</td><td>${cart[p.id]}</td><td>$${(p.price*cart[p.id]).toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:20px">Receipt to ${escapeHTML(email)}<br>${shipping==='express'?'Express delivery: $12.00':'Standard delivery: free'}<br>${coupon?'Discount: 10%':'No discount'}</p><h2>Total: <span data-testid="order-total">$${total().toFixed(2)}</span></h2><div class="row"><button class="secondary" id="back">Back to delivery</button><button id="place">Place order</button></div>`;$('#back').onclick=()=>{step=2;draw();};$('#place').onclick=async()=>{const button=$('#place');button.disabled=true;$('#back').disabled=true;result('Placing order…');try{const response=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:Object.fromEntries(Object.entries(cart).filter(([,q])=>q>0)),email,coupon,shipping}),signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Order failed');body.innerHTML=`<span class="tag">Order confirmed</span><h2 style="margin-top:20px">Thank you for practicing.</h2><p>Order <strong data-testid="order-id">${escapeHTML(data.id)}</strong></p><h3>Paid: $${Number(data.total).toFixed(2)}</h3><button id="again">Start new order</button>`;result('Your practice order is complete. No payment was taken.');$('#again').onclick=()=>render();}catch(e){if(e.name!=='AbortError'){result(`Order failed: ${e.message}. You can retry.`,true);button.disabled=false;$('#back').disabled=false;}}};}}
 draw();
}
function storage(){
 const user=sessionStorage.getItem('lab-session');const theme=localStorage.getItem('lab-theme')||'Sage';panel.innerHTML=`<h2>Practice account</h2>${user?`<div class="result">Signed in as <strong>${escapeHTML(user)}</strong></div><button id="logout" style="margin-top:20px">Sign out</button>`:`<p class="muted">Demo credentials: learner@example.com / practice123</p><form id="login"><div class="field"><label for="login-email">Email</label><input type="email" id="login-email" required></div><div class="field"><label for="password">Password</label><input type="password" id="password" required></div><button>Sign in</button></form>`}<div class="divider"></div><div class="field"><label for="theme">Saved accent preference</label><select id="theme"><option>Sage</option><option>Ocean</option><option>Amber</option></select></div><div id="swatch" style="height:40px;border-radius:7px"></div>${status()}`;$('#theme').value=theme;const update=()=>{$('#swatch').style.background={Sage:'#9eba87',Ocean:'#6c9fb5',Amber:'#dcb16c'}[$('#theme').value];};update();$('#theme').onchange=()=>{localStorage.setItem('lab-theme',$('#theme').value);update();result(`Preference saved: ${$('#theme').value}`);};if(user){$('#logout').onclick=()=>{sessionStorage.removeItem('lab-session');storage();};}else{$('#login').onsubmit=e=>{e.preventDefault();if($('#login-email').value==='learner@example.com'&&$('#password').value==='practice123'){sessionStorage.setItem('lab-session',$('#login-email').value);storage();}else result('Incorrect email or password',true);};}
}
render();
